def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my_last, opp_last = history[-1]
    # Always defect if opponent has defected very recently
    if opp_last == 'D':
        return 'D'
    # Count cumulative opponent defections
    opp_def = sum(1 for _, o in history if o == 'D')
    my_def = sum(1 for m, _ in history if m == 'D')
    # Tolerate a small number of early defections, then retaliate
    if opp_def == 0:
        # Cooperative opening, but occasionally test if we're too naive
        if n > 20 and my_def == 0 and rng.random() < 0.05:
            return 'D'
        return 'C'
    # Opponent has defected at least once in the past
    # If they defected recently, punish
    recent = history[-3:] if n >= 3 else history
    recent_opp_def = sum(1 for _, o in recent if o == 'D')
    if recent_opp_def >= 1:
        return 'D'
    # If they've mostly cooperated since their last defection, return to cooperation
    if n >= 10:
        last_def_idx = -1
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                last_def_idx = i
                break
        if last_def_idx >= 0:
            since_def = history[last_def_idx + 1:]
            if len(since_def) >= 5 and all(o == 'C' for _, o in since_def):
                return 'C'
    # Default to cooperation to avoid endless mutual defection
    return 'C'

